response.text:
{
  "modName": "counter_8bit",
  "domain": "General Purpose Counter",
  "requirements": [
    {
      "id": "REQ-FUNC-001",
      "cat": "Functionality",
      "pri": "Must",
      "desc": "The module shall increment the count on a rising clock edge when 'up' is asserted and decrement when 'down' is asserted.",
      "rat": "[derived from description: When en is high on a rising clock edge, count increments if up else decrements]"
    },
    {
      "id": "REQ-FUNC-002",
      "cat": "Functionality",
      "pri": "Must",
      "desc": "The count value shall saturate at 255 when attempting to increment from 255 and at 0 when attempting to decrement below 0.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-FUNC-003",
      "cat": "Functionality",
      "pri": "Must",
      "desc": "The reset signal shall asynchronously set the count to zero when asserted.",
      "rat": "[domain default]"
    },
    {
      "id": "REQ-TIM-001",
      "cat": "Timing",
      "pri": "Must",
      "desc": "Count updates occur only on a rising edge of the clock.",
      "rat": ""
    },
    {
      "id": "REQ-TIM-002",
      "cat": "Timing",
      "pri": "Should",
      "desc": "The counter shall maintain its state between clock edges when 'en' is low.",
      "rat": ""
    },
    {
      "id": "REQ-INTF-001",
      "cat": "Interface",
      "pri": "Must",
      "desc": "The module shall have exactly one asynchronous active-low reset input named 'rst_n'.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-INTF-002",
      "cat": "Interface",
      "pri": "Must",
      "desc": "The module shall have exactly one system clock input named 'clk' with rising-edge activation.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-INTF-003",
      "cat": "Interface",
      "pri": "Must",
      "desc": "The module shall have exactly one data input named 'data_i' of width DATA_W.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-INTF-004",
      "cat": "Interface",
      "pri": "Must",
      "desc": "The module shall have exactly one data output named 'count' representing the current count value.",
      "rat": "[assumed]"
    },
    {
      "id": "REQ-VERIF-001",
      "cat": "Verification",
      "pri": "Should",
      "desc": "A testbench shall be provided to verify that the counter behaves correctly under all input conditions.",
      "rat": ""
    }
  ],
  "iface": [
    { "name": "clk",    "dir": "input",  "width": "1",      "desc": "System clock, rising-edge active" },
    { "name": "rst_n",  "dir": "input",  "width": "1",      "desc": "Asynchronous active-low reset" },
    { "name": "data_i", "dir": "input",  "width": "DATA_W",  "desc": "Write data bus" },
    { "name": "count",  "dir": "output", "width": "8",   "desc": "Current count value" }
  ],
  "params": [
    { "name": "DATA_W", "type": "parameter", "def": 8, "range": "[1:1024]", "desc": "Data-path width in bits" }
  ]
}
